  /**
   * Discard specific file(s) from a task's worktree
   * Uses git restore to reset files to their state in the base branch
   */
  ipcMain.handle(
    IPC_CHANNELS.TASK_WORKTREE_DISCARD_FILES,
    async (_, taskId: string, filePaths: string[]): Promise<IPCResult<{ success: boolean; message: string; filesDiscarded: string[] }>> => {
      try {
        const { task, project } = findTaskAndProject(taskId);
        if (!task || !project) {
          return { success: false, error: 'Task not found' };
        }
        // Per-spec worktree path: .worktrees/{spec-name}/
        const worktreePath = path.join(project.path, '.worktrees', task.specId);
        if (!existsSync(worktreePath)) {
          return { success: false, error: 'No worktree found for this task' };
        }
        const filesDiscarded: string[] = [];
        const errors: string[] = [];
        // Discard each file individually
        for (const filePath of filePaths) {
          try {
            // Use git restore to reset the file to the base branch version
            // This works for modified, added, and deleted files
            execSync(`git restore --source=HEAD --staged --worktree -- "${filePath}"`, {
              cwd: worktreePath,
              encoding: 'utf-8'
            });
            filesDiscarded.push(filePath);
          } catch (error) {
            // If the file was added (doesn't exist in base), remove it entirely
            try {
              const fullPath = path.join(worktreePath, filePath);
              if (existsSync(fullPath)) {
                execSync(`git rm -f "${filePath}"`, {
                  cwd: worktreePath,
                  encoding: 'utf-8'
                });
                filesDiscarded.push(filePath);
              } else {
                errors.push(`${filePath}: File not found`);
              }
            } catch (rmError) {
              errors.push(`${filePath}: ${rmError instanceof Error ? rmError.message : 'Failed to remove'}`);
            }
          }
        }
        if (filesDiscarded.length === 0) {
          return {
            success: false,
            error: `No files were discarded. Errors: ${errors.join('; ')}`
          };
        }
        const message = filesDiscarded.length === filePaths.length
          ? `Successfully discarded ${filesDiscarded.length} file(s)`
          : `Discarded ${filesDiscarded.length} of ${filePaths.length} file(s). Errors: ${errors.join('; ')}`;
        return {
          success: true,
          data: {
            success: true,
            message,
            filesDiscarded
          }
        };
      } catch (error) {
        console.error('Failed to discard files:', error);
        return {
          success: false,
          error: error instanceof Error ? error.message : 'Failed to discard files'
        };
      }
    }
  );
```
