### 5. Update DiffViewDialog Component
**File:** `apps/frontend/src/renderer/components/task-detail/task-review/DiffViewDialog.tsx`
Replace the entire file with:
```typescript
import { useState } from 'react';
import { Eye, FileCode, X, Loader2 } from 'lucide-react';
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '../../ui/alert-dialog';
import { Badge } from '../../ui/badge';
import { Button } from '../../ui/button';
import { cn } from '../../../lib/utils';
import type { WorktreeDiff } from '../../../../shared/types';
interface DiffViewDialogProps {
  open: boolean;
  worktreeDiff: WorktreeDiff | null;
  taskId?: string;
  onOpenChange: (open: boolean) => void;
  onFileDiscarded?: () => void;
}
/**
 * Dialog displaying the list of changed files with their status and line changes
 * Now includes the ability to discard individual files
 */
export function DiffViewDialog({
  open,
  worktreeDiff,
  taskId,
  onOpenChange,
  onFileDiscarded
}: DiffViewDialogProps) {
  const [discardingFile, setDiscardingFile] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const handleDiscardFile = async (filePath: string) => {
    if (!taskId) return;
    setDiscardingFile(filePath);
    setError(null);
    try {
      const result = await window.api.task.discardWorktreeFiles(taskId, [filePath]);
      if (result.success && result.data) {
        // Notify parent to refresh the diff
        onFileDiscarded?.();
      } else {
        setError(result.error || 'Failed to discard file');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to discard file');
    } finally {
      setDiscardingFile(null);
    }
  };
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent className="max-w-2xl max-h-[80vh] overflow-hidden flex flex-col">
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center gap-2">
            <Eye className="h-5 w-5 text-purple-400" />
            Changed Files
          </AlertDialogTitle>
          <AlertDialogDescription>
            {worktreeDiff?.summary || 'No changes found'}
          </AlertDialogDescription>
        </AlertDialogHeader>
        {error && (
          <div className="px-4 py-2 bg-destructive/10 text-destructive text-sm rounded-lg">
            {error}
          </div>
        )}
        <div className="flex-1 overflow-auto min-h-0 -mx-6 px-6">
          {worktreeDiff?.files && worktreeDiff.files.length > 0 ? (
            <div className="space-y-2">
              {worktreeDiff.files.map((file, idx) => (
                <div
                  key={idx}
                  className="flex items-center justify-between p-2 rounded-lg bg-secondary/30 hover:bg-secondary/50 transition-colors group"
                >
                  <div className="flex items-center gap-2 min-w-0 flex-1">
                    <FileCode className={cn(
                      'h-4 w-4 shrink-0',
                      file.status === 'added' && 'text-success',
                      file.status === 'deleted' && 'text-destructive',
                      file.status === 'modified' && 'text-info',
                      file.status === 'renamed' && 'text-warning'
                    )} />
                    <span className="text-sm font-mono truncate">{file.path}</span>
                  </div>
                  <div className="flex items-center gap-2 shrink-0 ml-2">
                    <Badge
                      variant="secondary"
                      className={cn(
                        'text-xs',
                        file.status === 'added' && 'bg-success/10 text-success',
                        file.status === 'deleted' && 'bg-destructive/10 text-destructive',
                        file.status === 'modified' && 'bg-info/10 text-info',
                        file.status === 'renamed' && 'bg-warning/10 text-warning'
                      )}
                    >
                      {file.status}
                    </Badge>
                    <span className="text-xs text-success">+{file.additions}</span>
                    <span className="text-xs text-destructive">-{file.deletions}</span>
                    {/* Discard button - only show when taskId is provided */}
                    {taskId && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-6 w-6 p-0 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-destructive/10 hover:text-destructive"
                        onClick={() => handleDiscardFile(file.path)}
                        disabled={discardingFile === file.path}
                        title="Discard this file"
                      >
                        {discardingFile === file.path ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : (
                          <X className="h-3 w-3" />
                        )}
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8 text-muted-foreground">
              No changed files found
            </div>
          )}
        </div>
        <AlertDialogFooter className="mt-4">
          <AlertDialogCancel>Close</AlertDialogCancel>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
```
